#include <bits/stdc++.h>
using namespace std;
const int MOD = 777777777;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    if (!(cin >> n >> k)) return 0;
    int s = n - k;
    // Since k >= 1, we don't need to handle s == n case.
    // Precompute combinations C[n][k] mod MOD
    vector<vector<int>> C(n + 1, vector<int>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = C[i-1][j-1] + C[i-1][j];
            if (C[i][j] >= MOD) C[i][j] -= MOD;
        }
    }
    // Compute answer using inclusion-exclusion over subsets of {1..n} \ {s}
    vector<int> vals;
    for (int v = 1; v <= n; ++v) if (v != s) vals.push_back(v);
    int m = vals.size(); // m = n-1
    long long sum = 0;
    // total subsets = 2^m <= 2^27 ~ 1.3e8, iterate via bitmask
    int total_masks = 1 << m;
    // To speed up, we can iterate and break early when sum of selected values > k.
    for (int mask = 0; mask < total_masks; ++mask) {
        int sumT = 0;
        int cnt = 0;
        long long term = 1;
        int rem = k;
        bool ok = true;
        // iterate through bits
        int mm = mask;
        int idx = 0;
        while (mm) {
            if (mm & 1) {
                int v = vals[idx];
                sumT += v;
                if (sumT > k) { ok = false; break; }
                term = term * C[rem][v] % MOD;
                rem -= v;
                cnt++;
            }
            idx++;
            mm >>= 1;
        }
        if (!ok) continue;
        // rem is k - sumT
        int ways_remaining = 1;
        // compute m^rem mod MOD
        // m = n-1
        long long base = m;
        int exp = rem;
        long long pow_m = 1;
        while (exp) {
            if (exp & 1) pow_m = pow_m * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        ways_remaining = (int)pow_m;
        term = term * ways_remaining % MOD;
        if (cnt % 2 == 0) {
            sum += term;
        } else {
            sum -= term;
        }
        if (sum >= MOD) sum -= MOD;
        if (sum < 0) sum += MOD;
    }
    // Multiply by C(n, s)
    long long ans = sum * C[n][s] % MOD;
    cout << ans % MOD << "\n";
    return 0;
}
